use sdk::*;

#[derive(Default)]
struct Contract;

/// If we abort, it's with this type
#[derive(ReadXDR, WriteXDR)]
#[repr(i32)]
pub enum AbortType {
    Sys(SyscallExn2),
    Other,
}

#[contract(client = ContractClient, /* abort = AbortType */)]
impl Contract {
    pub fn uncaught_abort() {
        with_debug_context!("This may lead to sadness", {
            abort(&"Sadness");
        });
    }

    pub fn bad_bytestring_length() -> u32 {
        // TODO: This wrapper will be generated by the contract macro for each
        // method.
        with_abort_handler(&abort_handler, || {
            //
            // This should abort with a `SyscallExn` because the storage location is empty
            //
            asys::bytestring_get_len(&StorageKey::from([72; 32]))
        })
    }

    pub fn do_contract_abort() {
        with_abort_handler(&abort_handler, || {
            let buf = [0, 1, 2, 4, 5];

            contract_abort(&buf);
        });
    }
}

// From the given abort info, construct our contract's `AbortType` value and
// call `contract_abort` with it.
//
pub fn abort_handler<'a>(info: AbortInfo<'a>) -> Never {
    use core::any::Any;

    let any_payload = info.payload() as &dyn Any;

    if let Some(e) = any_payload.downcast_ref::<SyscallExn>() {
        let e2: SyscallExn2 = (*e).into(); // temp hack

        contract_abort_encoded(&e2);
    } else {
        contract_abort_encoded(&AbortType::Other);
    }
}
